using System.Reflection;
namespace CaptureZoo;
internal static class OcrTests
{
 internal static int Run()
 {
  string root=Path.Combine(Environment.CurrentDirectory,"work","capture-ocr-check");Directory.CreateDirectory(root);var checks=new List<string>();string? prior=OcrModelStore.TestRoot,language=UiLanguage.TestLanguage;var downloader=OcrModelStore.TestDownload;
  void Check(bool ok,string text){if(!ok)throw new Exception(text);checks.Add("PASS "+text);}
  void Await(Task task){while(!task.IsCompleted){Application.DoEvents();Thread.Sleep(2);}task.GetAwaiter().GetResult();}
  T AwaitResult<T>(Task<T> task){Await(task);return task.GetAwaiter().GetResult();}
  try{
   ApplicationConfiguration.Initialize();OcrSelectionTests.Run();Check(true,"Right-drag crop, scaled coordinates, Esc and clipboard isolation");OcrModelStore.TestRoot=Path.Combine(root,"bad-model-"+Guid.NewGuid().ToString("N"));
   OcrModelStore.TestDownload=(_,_)=>Task.FromResult<Stream>(new MemoryStream(new byte[50]));bool rejected=false;try{Await(OcrModelStore.EnsureAsync(null,CancellationToken.None));}catch(InvalidDataException){rejected=true;}
   Check(rejected&&!OcrModelStore.Ready()&&!Directory.EnumerateFiles(OcrModelStore.Root).Any(),"Invalid download rejected and partial files cleaned");
   OcrModelStore.TestRoot=Path.Combine(root,"models");OcrModelStore.TestDownload=null;Await(OcrModelStore.EnsureAsync(null,CancellationToken.None));Check(OcrModelStore.Ready(),"Official models downloaded and SHA256 verified");
   int network=0;OcrModelStore.TestDownload=(_,_)=>{network++;throw new IOException("Offline test");};Await(OcrModelStore.EnsureAsync(null,CancellationToken.None));Check(network==0,"Cached models work offline without a second download");
   using var image=new Bitmap(1100,230);using(var g=Graphics.FromImage(image)){g.Clear(Color.White);g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;using var font=new Font("Meiryo",27);g.DrawString("日本語の文字を読み取ります。",font,Brushes.Black,30,20);g.DrawString("CaptureZoo OCR test 12345",font,Brushes.Black,30,95);}image.Save(Path.Combine(root,"fixture.png"));
   var result=AwaitResult(OcrService.ReadAsync(image,CancellationToken.None));Check(result.Text.Contains("日本語の文字を読み取ります。")&&result.Text.Contains("CaptureZoo OCR test 12345"),"Mixed Japanese and English text recognised exactly");Check(result.Lines>=2&&network==0,"Recognition runs locally after preparation");
   using(var small=new Bitmap(1000,160)){using(var g=Graphics.FromImage(small)){g.Clear(Color.White);g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;using var font=new Font("Meiryo UI",13);g.DrawString("コピーした画像から文字を読み取れます。",font,Brushes.Black,25,25);g.DrawString("CaptureZoo text capture",font,Brushes.Black,25,75);}var smallResult=AwaitResult(OcrService.ReadAsync(small,CancellationToken.None));Check(smallResult.Text.Contains("コピーした画像から文字を読み取れます")&&smallResult.Text.Contains("CaptureZoo text capture"),"Screenshot-size Japanese and English text recognised");small.Save(Path.Combine(root,"small-text.png"));}
   using(var blank=new Bitmap(300,120)){using(var g=Graphics.FromImage(blank))g.Clear(Color.White);Check(string.IsNullOrWhiteSpace(AwaitResult(OcrService.ReadAsync(blank,CancellationToken.None)).Text),"Blank image produces no fabricated text");}
   using(var cancelled=new CancellationTokenSource()){cancelled.Cancel();bool stopped=false;try{Await(OcrService.ReadAsync(image,cancelled.Token));}catch(OperationCanceledException){stopped=true;}Check(stopped,"Cancellation prevents a pending recognition");}
   UiLanguage.TestLanguage="en";int copies=0;string copied="";using(var dialog=new OcrDialog(image,s=>{copies++;copied=s;},(_,_,_)=>Task.FromResult(result))){Exception? failure=null;using var timer=new System.Windows.Forms.Timer{Interval=60};timer.Tick+=(_,_)=>{try{var text=(RichTextBox)typeof(OcrDialog).GetField("text",BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(dialog)!;if(text.ReadOnly)return;timer.Stop();var copy=(Button)typeof(OcrDialog).GetField("copy",BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(dialog)!;Check(dialog.Text=="Read text (OCR)"&&copy.Text=="Copy text","OCR result dialog supports English");Check(copies==0,"Recognition does not overwrite the image clipboard");using(var recognisedShot=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(recognisedShot,new Rectangle(Point.Empty,recognisedShot.Size));recognisedShot.Save(Path.Combine(root,"recognised-results.png"));}text.Text="User edited text";copy.PerformClick();Check(copies==1&&copied==text.Text,"Copy button copies the edited result only");using var shot=new Bitmap(dialog.Width,dialog.Height);dialog.DrawToBitmap(shot,new Rectangle(Point.Empty,shot.Size));shot.Save(Path.Combine(root,"english-results.png"));dialog.Close();}catch(Exception error){failure=error;dialog.Close();}};timer.Start();dialog.ShowDialog();if(failure!=null)throw failure;Check(copies==1,"Closing OCR does not copy again");}
   UiLanguage.TestLanguage="ja";bool cancelledUi=false;using(var dialog=new OcrDialog(image,_=>throw new Exception("Cancel copied text"),async(_,_,token)=>{try{await Task.Delay(Timeout.Infinite,token);}catch(OperationCanceledException){cancelledUi=true;throw;}return result;})){using var timer=new System.Windows.Forms.Timer{Interval=60};timer.Tick+=(_,_)=>{timer.Stop();dialog.Close();};timer.Start();dialog.ShowDialog();for(int i=0;i<10;i++){Application.DoEvents();Thread.Sleep(5);}}Check(cancelledUi,"Closing busy OCR cancels the request without copying");
   File.WriteAllText(Path.Combine(root,"result.json"),System.Text.Json.JsonSerializer.Serialize(new{Passed=true,Seconds=result.Seconds,Lines=result.Lines,Text=result.Text,Checks=checks},new System.Text.Json.JsonSerializerOptions{WriteIndented=true}));return 0;
  }catch(Exception error){checks.Add(error.ToString());File.WriteAllLines(Path.Combine(root,"failure.txt"),checks);return 1;}finally{OcrModelStore.TestRoot=prior;OcrModelStore.TestDownload=downloader;UiLanguage.TestLanguage=language;}
 }
}
